from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')

# Supabase browser client.
if 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2' not in s:
    s = s.replace('</head>', '<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script></head>', 1)

# Review section CSS. Mobile is one large swipe card with a peek of the next card.
css = r'''
/* testra-review-feed-v2 */
.testi{background:radial-gradient(circle at 88% 10%,#fff0e6 0,transparent 28%),radial-gradient(circle at 10% 88%,#eaf3ff 0,transparent 30%),#fff;padding:88px 0 104px;overflow:hidden}.testi .section-head{margin-bottom:32px}.testi .section-head h2{font-size:clamp(38px,5vw,58px);line-height:1.05;margin:10px 0 0;color:#0a1128}.testi-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.testi-card{background:#fff;border:1px solid #e1e5ef;border-radius:28px;padding:24px;box-shadow:0 18px 48px rgba(10,17,40,.08);min-width:0}.testi-card.has-photo{padding:0;overflow:hidden}.testi-card .review-photo{width:100%;aspect-ratio:4/3;object-fit:cover;display:block;background:#f2f4fa}.testi-card.has-photo .review-body{padding:22px 24px 24px}.testi-card .stars{color:#ffb100;font-size:20px;letter-spacing:2px;line-height:1}.testi-card .quote{font-size:17px;line-height:1.65;color:#252a3e;margin:18px 0 22px}.testi-card .testi-who{display:flex;align-items:center;gap:11px}.testi-card .testi-avatar{width:38px;height:38px;border-radius:50%;background:linear-gradient(145deg,#1746ff,#0b2aa9);display:grid;place-items:center;color:#fff;font-weight:800;flex:0 0 auto}.testi-card .testi-name{font-weight:800;color:#0a1128}.testi-card .testi-date{font-size:11px;color:#8a90a4;margin-top:2px}.testi-empty{grid-column:1/-1;text-align:center;padding:32px;color:#6b7091;background:#f7f7fb;border-radius:24px;border:1px solid #e4e5f1}@media(max-width:900px){.testi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.testi{padding:68px 0 82px}.testi .section-head{margin-bottom:26px}.testi-grid{display:flex;gap:14px;overflow-x:auto;scroll-snap-type:x mandatory;scroll-padding-left:18px;padding:4px 18px 18px;margin-left:-18px;margin-right:-18px;-webkit-overflow-scrolling:touch;scrollbar-width:none}.testi-grid::-webkit-scrollbar{display:none}.testi-card{flex:0 0 86%;scroll-snap-align:start;border-radius:26px;padding:22px}.testi-card.has-photo{padding:0}.testi-card.has-photo .review-body{padding:20px 22px 23px}.testi-card .quote{font-size:17px;line-height:1.6}.testi-empty{flex:0 0 92%;text-align:left}}

/* testra-pricing-v3 */
#order{padding:72px 18px 92px;background:#fff}.testra-offer{position:relative;overflow:hidden;max-width:1120px;margin:auto;padding:52px 34px 38px;border-radius:42px;background:linear-gradient(155deg,#ffb000 0%,#ff641c 38%,#8c52a7 69%,#1746ff 100%);box-shadow:0 26px 70px rgba(30,51,118,.18)}.testra-offer:before{content:"";position:absolute;width:520px;height:520px;border-radius:50%;right:-250px;top:-260px;background:rgba(255,255,255,.13);filter:blur(34px)}.testra-offer-inner{position:relative;z-index:1}.testra-offer-head{text-align:center;color:#fff;max-width:720px;margin:0 auto 34px}.testra-offer-kicker{display:inline-flex;padding:9px 15px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.12);border-radius:999px;font-size:12px;font-weight:800;letter-spacing:.08em}.testra-offer-head h2{font-size:clamp(38px,5vw,58px);line-height:1.04;margin:20px 0 12px}.testra-offer-head p{margin:0;color:rgba(255,255,255,.84);font-size:16px;line-height:1.6}.testra-plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.testra-plan{position:relative;overflow:hidden;cursor:pointer;border:1px solid rgba(255,255,255,.4);background:rgba(255,255,255,.12);border-radius:28px;color:#fff;transition:.2s transform,.2s background,.2s box-shadow}.testra-plan.active{background:#fff;color:#0a1128;transform:translateY(-4px);box-shadow:0 20px 42px rgba(20,27,80,.22);border-color:#fff}.testra-plan-media{height:210px;background:#fff;display:grid;place-items:center;overflow:hidden}.testra-plan-media img{width:100%;height:100%;object-fit:cover;display:block}.testra-plan-copy{padding:20px 20px 22px}.testra-plan-top{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.testra-plan-name{font-size:18px;font-weight:800}.testra-plan-price{font:700 34px Fraunces,serif;margin-top:6px}.testra-plan-per{font-size:12px;opacity:.72;margin-top:4px}.testra-save{display:inline-flex;padding:7px 9px;border-radius:999px;background:rgba(255,255,255,.16);font-size:10px;font-weight:800;white-space:nowrap}.testra-plan.active .testra-save{background:#fff0d8;color:#c45d00}.testra-popular{position:absolute;right:14px;top:14px;z-index:2;background:#0a1128;color:#fff;border-radius:999px;padding:7px 10px;font-size:10px;font-weight:900;letter-spacing:.05em}.testra-order-btn{display:flex;align-items:center;justify-content:center;width:min(560px,100%);margin:28px auto 0;padding:17px 22px;border-radius:999px;background:#fff;color:#0a1128;font-size:17px;font-weight:900;box-shadow:0 14px 30px rgba(16,25,72,.2)}.testra-offer-note{text-align:center;color:rgba(255,255,255,.78);font-size:12px;margin-top:12px}.testra-offer-chips{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin-top:18px}.testra-offer-chip{padding:7px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.08);color:#fff;font-size:11px;font-weight:700}@media(max-width:820px){.testra-plans{grid-template-columns:1fr}.testra-plan{display:grid;grid-template-columns:42% 58%;min-height:190px}.testra-plan-media{height:100%;min-height:190px}.testra-plan.active{transform:none}.testra-plan-copy{display:flex;flex-direction:column;justify-content:center}.testra-popular{top:10px;right:10px}}@media(max-width:520px){#order{padding:56px 12px 72px}.testra-offer{padding:38px 16px 28px;border-radius:34px}.testra-offer-head{margin-bottom:25px}.testra-offer-head h2{font-size:38px}.testra-offer-head p{font-size:14px}.testra-plan{grid-template-columns:44% 56%;border-radius:24px;min-height:164px}.testra-plan-media{min-height:164px}.testra-plan-copy{padding:15px 14px}.testra-plan-name{font-size:16px}.testra-plan-price{font-size:30px}.testra-plan-per{font-size:11px}.testra-save{font-size:9px;padding:6px 8px}.testra-popular{font-size:9px}.testra-order-btn{font-size:16px;padding:16px 18px}}
'''
if '/* testra-review-feed-v2 */' not in s:
    s = s.replace('</style>', css + '</style>', 1)
elif '/* testra-pricing-v3 */' not in s:
    pricing_css = css.split('/* testra-pricing-v3 */',1)[1]
    s = s.replace('</style>', '/* testra-pricing-v3 */' + pricing_css + '</style>', 1)

# Replace the complete legacy testimonial section, regardless of its old card contents.
section = '''<section class="testi" id="testimoni"><div class="wrap"><div class="section-head"><div class="eyebrow-sm"><span data-lang="bm">APA KATA MEREKA</span><span data-lang="en">WHAT THEY SAY</span></div><h2><span data-lang="bm">Pengalaman pelanggan.</span><span data-lang="en">Customer experiences.</span></h2></div><div class="testi-grid" id="testimonialGrid"><div class="testi-empty"><span data-lang="bm">Memuatkan review pelanggan...</span><span data-lang="en">Loading customer reviews...</span></div></div></div></section>'''
s, n = re.subn(r'<section class="testi" id="testimoni">.*?</section>', section, s, count=1, flags=re.S)
if n != 1:
    raise SystemExit('testimonial section not found exactly once')

# Enhanced pricing section using the three final product bundle visuals uploaded to assets.
pricing = '''<section id="order"><div class="testra-offer"><div class="testra-offer-inner"><div class="testra-offer-head"><div class="testra-offer-kicker"><span data-lang="bm">PROMOSI PENGENALAN</span><span data-lang="en">INTRODUCTORY OFFER</span></div><h2><span data-lang="bm">Pilih Bekalan TESTRA Anda.</span><span data-lang="en">Choose Your TESTRA Supply.</span></h2><p><span data-lang="bm">Lebih banyak kotak, lebih rendah kos setiap kotak. Pilih bekalan yang sesuai dengan rutin anda.</span><span data-lang="en">More boxes, lower cost per box. Choose the supply that fits your routine.</span></p></div><div class="testra-plans" id="testraPlans"><article class="testra-plan" data-label-bm="1 Kotak — RM79" data-label-en="1 Box — RM79"><div class="testra-plan-media"><img src="assets/ChatGPT Image Aug 9, 2026, 08_57_04 PM.png" alt="TESTRA 1 kotak" loading="lazy"></div><div class="testra-plan-copy"><div class="testra-plan-top"><div><div class="testra-plan-name"><span data-lang="bm">1 Kotak</span><span data-lang="en">1 Box</span></div><div class="testra-plan-price">RM79</div><div class="testra-plan-per">RM79.00 / kotak</div></div><span class="testra-save"><span data-lang="bm">CUBA DULU</span><span data-lang="en">TRY FIRST</span></span></div></div></article><article class="testra-plan active" data-label-bm="3 Kotak — RM199" data-label-en="3 Boxes — RM199"><span class="testra-popular"><span data-lang="bm">PALING POPULAR</span><span data-lang="en">MOST POPULAR</span></span><div class="testra-plan-media"><img src="assets/ChatGPT Image Aug 9, 2026, 08_57_18 PM.png" alt="TESTRA 3 kotak" loading="lazy"></div><div class="testra-plan-copy"><div class="testra-plan-top"><div><div class="testra-plan-name"><span data-lang="bm">3 Kotak</span><span data-lang="en">3 Boxes</span></div><div class="testra-plan-price">RM199</div><div class="testra-plan-per">RM66.33 / kotak</div></div><span class="testra-save"><span data-lang="bm">JIMAT RM38</span><span data-lang="en">SAVE RM38</span></span></div></div></article><article class="testra-plan" data-label-bm="6 Kotak — RM359" data-label-en="6 Boxes — RM359"><div class="testra-plan-media"><img src="assets/ChatGPT Image Aug 9, 2026, 08_57_42 PM.png" alt="TESTRA 6 kotak" loading="lazy"></div><div class="testra-plan-copy"><div class="testra-plan-top"><div><div class="testra-plan-name"><span data-lang="bm">6 Kotak</span><span data-lang="en">6 Boxes</span></div><div class="testra-plan-price">RM359</div><div class="testra-plan-per">RM59.83 / kotak</div></div><span class="testra-save"><span data-lang="bm">JIMAT RM115</span><span data-lang="en">SAVE RM115</span></span></div></div></article></div><a id="testraOrderBtn" href="checkout.html" class="testra-order-btn"><span data-lang="bm">Pilih 3 Kotak — RM199 →</span><span data-lang="en">Choose 3 Boxes — RM199 →</span></a><div class="testra-offer-chips"><span class="testra-offer-chip"><span data-lang="bm">✓ 1 / 3 / 6 kotak</span><span data-lang="en">✓ 1 / 3 / 6 boxes</span></span><span class="testra-offer-chip"><span data-lang="bm">✓ Pilihan fleksibel</span><span data-lang="en">✓ Flexible choice</span></span><span class="testra-offer-chip"><span data-lang="bm">✓ Checkout ringkas</span><span data-lang="en">✓ Simple checkout</span></span></div><div class="testra-offer-note"><span data-lang="bm">Harga promosi dipaparkan sebelum checkout.</span><span data-lang="en">Promotional pricing is shown before checkout.</span></div></div></div></section>'''
s, n = re.subn(r'<section id="order">.*?</section>', pricing, s, count=1, flags=re.S)
if n != 1:
    raise SystemExit('pricing section not found exactly once')

# Remove any older injected review loader, then append the canonical loader and pricing selector.
s = re.sub(r'<script id="testra-review-loader">.*?</script>', '', s, flags=re.S)
s = re.sub(r'<script id="testra-pricing-selector">.*?</script>', '', s, flags=re.S)
loader = r'''<script id="testra-review-loader">
(()=>{
  const reviewSb=supabase.createClient('https://aytmfuevvoumobwfqptc.supabase.co','sb_publishable_Uol-itavAcZy4ciP3gbqJg_Ea9sw1TS');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials=v=>String(v||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
  const dateLabel=v=>{try{return new Intl.DateTimeFormat(document.body.classList.contains('lang-en')?'en-MY':'ms-MY',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v))}catch(_){return ''}};
  async function loadTestimonials(){
    const grid=document.getElementById('testimonialGrid');if(!grid)return;
    const {data,error}=await reviewSb.from('reviews').select('customer_name,rating,comment,image_url,created_at').eq('is_published',true).order('created_at',{ascending:false}).limit(12);
    if(error){console.error('Review load failed',error);grid.innerHTML='<div class="testi-empty">Review belum dapat dimuatkan.</div>';return;}
    if(!data?.length){grid.innerHTML='<div class="testi-empty"><span data-lang="bm">Belum ada review pelanggan.</span><span data-lang="en">No customer reviews yet.</span></div>';return;}
    grid.innerHTML=data.map(r=>{const photo=r.image_url?`<img class="review-photo" src="${esc(r.image_url)}" alt="Review ${esc(r.customer_name)}" loading="lazy">`:'';const stars='★'.repeat(Math.max(0,Math.min(5,Number(r.rating)||0)))+'☆'.repeat(Math.max(0,5-(Number(r.rating)||0)));return `<article class="testi-card ${r.image_url?'has-photo':''}">${photo}<div class="review-body"><div class="stars" aria-label="${Number(r.rating)||0} daripada 5">${stars}</div><p class="quote">“${esc(r.comment||'')}”</p><div class="testi-who"><div class="testi-avatar">${esc(initials(r.customer_name))}</div><div><div class="testi-name">${esc(r.customer_name)}</div><div class="testi-date">${esc(dateLabel(r.created_at))}</div></div></div></div></article>`}).join('');
  }
  loadTestimonials();
})();
</script>'''
pricing_js = r'''<script id="testra-pricing-selector">
(()=>{const plans=[...document.querySelectorAll('.testra-plan')],btn=document.getElementById('testraOrderBtn');if(!plans.length||!btn)return;const paint=plan=>{plans.forEach(x=>x.classList.toggle('active',x===plan));const en=document.body.classList.contains('lang-en');const label=en?plan.dataset.labelEn:plan.dataset.labelBm;btn.innerHTML=en?`<span data-lang="en">Choose ${label} →</span>`:`<span data-lang="bm">Pilih ${label} →</span>`};plans.forEach(p=>p.addEventListener('click',()=>paint(p)));document.querySelectorAll('[data-setlang]').forEach(x=>x.addEventListener('click',()=>setTimeout(()=>paint(document.querySelector('.testra-plan.active')||plans[1]||plans[0]),0)));})();
</script>'''
s = s.replace('</body>', loader + pricing_js + '</body>', 1)

p.write_text(s, encoding='utf-8')
